seq = ""
with open("region.fasta") as f:
    for line in f:
        if line.startswith(">"):
            continue
        seq += line.strip()

comp = str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]
stop=set(["TAA","TAG","TGA"])

def find_orfs(s):
    res=[]
    for frame in range(3):
        i=frame
        while i<=len(s)-3:
            if s[i:i+3]=="ATG":
                j=i+3
                while j<=len(s)-3 and s[j:j+3] not in stop:
                    j+=3
                if j-i>=150:   # >=50 aa
                    res.append((i,j,s[j:j+3]))
                i=j+3
            else:
                i+=3
    return res

